sysauto_script.script:
// ScopeBridge — Nightly Coverage Scan (scheduled job)
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
//
// Re-runs an incremental scan across the tracked scopes. The set of tracked
// scopes is read from the x_snb.ai.provider system property in production, or
// defaults to scanning no scopes (safely no-ops) when none are configured.
(function runNightlyCoverage() {
    var scanner = new x_snb.ScopeBridgeScanner();

    // In production, this reads a comma-separated list of scopes to track
    // from the x_snb.tracked.scopes system property. When unset, it is a
    // safe no-op (never scans an arbitrary scope without configuration).
    var tracked = gs.getProperty('x_snb.tracked.scopes', '');
    if (!tracked) {
        gs.info('ScopeBridge nightly scan: no tracked scopes configured, skipping');
        return;
    }

    var scopes = tracked.split(',');
    for (var i = 0; i < scopes.length; i++) {
        var scope = scopes[i].trim();
        if (!scope) { continue; }
        try {
            var scanSysId = scanner.run(scope, 'incremental');
            if (scanSysId) {
                gs.info('ScopeBridge nightly scan: completed for ' + scope + ' (scan ' + scanSysId + ')');
            } else {
                gs.error('ScopeBridge nightly scan: failed for ' + scope);
            }
        } catch (e) {
            gs.error('ScopeBridge nightly scan: unhandled error for ' + scope + ': ' + e.message);
        }
    }
})();
